/**
 * Calculate the median of a sequence of numbers.
 * 
 * @param values Array of numbers to calculate the median
 * @returns The median value
 * 
 * @example
 * ```ts
 * import { math } from 'lambda-toolkit';
 * const { calcMedian } = math;
 * 
 * const result = calcMedian([1, 2, 3, 4, 5]);
 * // result: 3
 * ```
 */
export function calcMedian(values: number[]): number;
